class Solution {
    public int maxProduct(int[] nums) {
        int maxEnding = nums[0];
        int minEnding = nums[0];
        int best = nums[0];

        for (int index = 1; index < nums.length; index++) {
            int value = nums[index];
            if (value < 0) {
                int temp = maxEnding;
                maxEnding = minEnding;
                minEnding = temp;
            }
            maxEnding = Math.max(value, maxEnding * value);
            minEnding = Math.min(value, minEnding * value);
            best = Math.max(best, maxEnding);
        }
        return best;
    }
}

class Solution {
    public int maxProduct(int[] nums) {
        int n = nums.length;
        int[] maxEnding = new int[n];
        int[] minEnding = new int[n];
        maxEnding[0] = nums[0];
        minEnding[0] = nums[0];
        int best = nums[0];

        for (int index = 1; index < n; index++) {
            int value = nums[index];
            int candidateWithMax = maxEnding[index - 1] * value;
            int candidateWithMin = minEnding[index - 1] * value;
            maxEnding[index] = Math.max(value, Math.max(candidateWithMax, candidateWithMin));
            minEnding[index] = Math.min(value, Math.min(candidateWithMax, candidateWithMin));
            best = Math.max(best, maxEnding[index]);
        }
        return best;
    }
}

class Solution {
    public int maxProduct(int[] nums) {
        int n = nums.length;
        int best = nums[0];
        int prefix = 1;
        int suffix = 1;

        for (int index = 0; index < n; index++) {
            if (prefix == 0) {
                prefix = 1;
            }
            if (suffix == 0) {
                suffix = 1;
            }
            prefix *= nums[index];
            suffix *= nums[n - 1 - index];
            best = Math.max(best, Math.max(prefix, suffix));
        }
        return best;
    }
}

class Solution {
    public int maxProduct(int[] nums) {
        int n = nums.length;
        int best = nums[0];
        int start = 0;

        while (start < n) {
            if (nums[start] == 0) {
                best = Math.max(best, 0);
                start++;
                continue;
            }

            int end = start;
            long total = 1;
            int negativeCount = 0;
            int firstNegative = -1;
            int lastNegative = -1;

            while (end < n && nums[end] != 0) {
                total *= nums[end];
                best = Math.max(best, nums[end]);
                if (nums[end] < 0) {
                    negativeCount++;
                    if (firstNegative == -1) {
                        firstNegative = end;
                    }
                    lastNegative = end;
                }
                end++;
            }

            if (negativeCount % 2 == 0) {
                best = Math.max(best, (int) total);
            } else {
                long dropPrefix = 1;
                for (int i = firstNegative + 1; i < end; i++) {
                    dropPrefix *= nums[i];
                }
                if (firstNegative + 1 < end) {
                    best = Math.max(best, (int) dropPrefix);
                }

                long dropSuffix = 1;
                for (int i = start; i < lastNegative; i++) {
                    dropSuffix *= nums[i];
                }
                if (start < lastNegative) {
                    best = Math.max(best, (int) dropSuffix);
                }
            }
            start = end;
        }
        return best;
    }
}

class Solution {
    public int maxProduct(int[] nums) {
        int best = nums[0];
        for (int start = 0; start < nums.length; start++) {
            int product = 1;
            for (int end = start; end < nums.length; end++) {
                product *= nums[end];
                best = Math.max(best, product);
            }
        }
        return best;
    }
}
